/**
 * Unit tests for TokenBuffer.writeEndArray
 */
public class TokenBuffer_writeEndArray_TriageGen2Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    @Test
    public void testWriteEndArray_AppendsTokenAndMovesContext() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        // Establish a hierarchy: Start Array -> Start Object
        buffer.writeStartArray();
        buffer.writeStartObject();

        // Current context should be the Object context
        JsonWriteContext objectContext = buffer.getOutputContext();
        assertNotNull(objectContext);

        // Perform writeEndArray
        buffer.writeEndArray();

        // 1. Verify the token is appended. 
        // We verify this by parsing it back.
        JsonParser parser = buffer.asParser();
        // The sequence was: [ { (end array)
        // Since we ended the array while an object was still open, 
        // the parser should see END_ARRAY as the next token after the object start.
        // However, TokenBuffer tracks tokens sequentially.

        // Let's check the token sequence specifically:
        // Sequence: START_ARRAY, START_OBJECT, END_ARRAY
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());

        // 2. Verify context moved up (Parent of Object context is Array context)
        // After writeEndArray, _writeContext should be the parent of the previous context
        JsonWriteContext currentContext = buffer.getOutputContext();
        JsonWriteContext parentContext = objectContext.getParent();

        // If the logic works: _writeContext = c (where c is parent)
        // Note: In TokenBuffer, the context transitions happen inside the method.
        // If we were in an object context, it should now be in the array context.
        // But since we ended the array, the context is now the parent of the object context.
        // Wait, the code says: c = _writeContext.getParent(); if (c != null) _writeContext = c;
        // So if we were in Object, we are now in Array.
        assertEquals(parentContext, currentContext);
    }

    @Test
    public void testWriteEndArray_RootLevelNoParent() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        // Start at root level (no parent)
        buffer.writeStartArray();

        // The context for the array is the root context (parent is null)
        JsonWriteContext arrayContext = buffer.getOutputContext();

        // The token AFTER writeStartArray is the array context.
        // The parent of the array context is null.
        // Let's verify the internal logic: if c != null, _writeContext = c.
        // If c is null, _writeContext remains the same.

        buffer.writeEndArray();

        // Verify token
        JsonParser parser = buffer.asParser();
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());

        // Verify context remains the same because parent was null
        assertEquals(arrayContext, buffer.getOutputContext());
    }

    @Test
    public void testWriteEndArray_DeepHierarchy() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        buffer.writeStartArray(); // Context 1
        buffer.writeStartArray(); // Context 2
        buffer.writeStartArray(); // Context 3

        JsonWriteContext context3 = buffer.getOutputContext();
        JsonWriteContext context2 = context3.getParent();
        JsonWriteContext context1 = context2.getParent();

        buffer.writeEndArray(); // Should move from Context 3 to Context 2

        assertEquals(context2, buffer.getOutputContext());

        buffer.writeEndArray(); // Should move from Context 2 to Context 1
        assertEquals(context1, buffer.getOutputContext());

        // Verify tokens
        JsonParser parser = buffer.asParser();
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.START_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
    }

    @Test
    public void testWriteEndArray_WithMockParser() throws IOException {
        // Testing the constructor and ensuring no exceptions with mock dependencies
        JsonParser mockParser = mock(JsonParser.class);
        TokenBuffer buffer = new TokenBuffer(mockParser);

        // Just verify it doesn't crash and handles the null parent case
        buffer.writeEndArray();

        JsonParser parser = buffer.asParser();
        assertEquals(JsonToken.END_ARRAY, parser.nextToken());
    }
}
